import csv
import io
import re


def parse_csv(raw_csv: str):
    expected_width = 3
    number_pattern = re.compile(
        r"^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$"
    )

    try:
        records = list(csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"'))
    except csv.Error:
        records = []

    records = [row for row in records if row and any(value != "" for value in row)]

    if not records:
        return {
            "columns": [f"column_{i + 1}" for i in range(expected_width)],
            "rows": [],
        }

    first = records[0]
    has_header = (
        len(first) <= expected_width
        and any(not number_pattern.match(value.strip()) for value in first)
    )

    header = records.pop(0) if has_header else []
    width = max(expected_width, len(header), *(len(row) for row in records))

    if has_header:
        columns = [value if value else f"column_{i + 1}" for i, value in enumerate(header)]
        columns.extend(f"column_{i + 1}" for i in range(len(columns), width))
    else:
        columns = [f"column_{i + 1}" for i in range(width)]

    rows = [row + [""] * (width - len(row)) for row in records]
    return {"columns": columns, "rows": rows}
